import { faker } from "@faker-js/faker";
import { createSlice } from "@reduxjs/toolkit";
import truncateString from "../../utils/truncate";
import axios from "../../utils/axios";
import { UpdateIsLoading } from "./auth";


function convertTimestamp({ seconds, nanos }) {
    // Create a Date object using the seconds and nanoseconds
    const date = new Date(seconds * 1000 + nanos / 1000000);

    // Format the date to the desired output: YYYY-MM-DDTHH:mm:ss.sss+00:00
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0'); // Months are zero-indexed
    const day = String(date.getUTCDate()).padStart(2, '0');
    const hours = String(date.getUTCHours()).padStart(2, '0');
    const minutes = String(date.getUTCMinutes()).padStart(2, '0');
    const secondsPart = String(date.getUTCSeconds()).padStart(2, '0');
    const milliseconds = String(date.getUTCMilliseconds()).padStart(3, '0');

    // Combine the parts to form the desired timestamp format
    return `${year}-${month}-${day}T${hours}:${minutes}:${secondsPart}.${milliseconds}+00:00`;
}


const initialState = {
    direct_chat: {
        conversations: [],
        messages: [],
        current_conversation: null,
        current_messages: [],
    },
    group_chat: {

    }
}

const slice = createSlice({
    name: "conversation",
    initialState,
    reducers: {
        fetchDirectConversations(state, action) {
            const user_id = window.localStorage.getItem("user_id");
            const list = action.payload.map((el) => {
                const this_user = el.participants.find(
                    (element) => element.id.toString() !== user_id
                );
                return {
                    id: el.id,
                    user_id: this_user?.id,
                    name: `${this_user?.firstName} ${this_user?.lastName}`,
                    email: this_user?.email,
                    online: this_user?.status === "ONLINE",
                    img: this_user?.avatar,
                    msg: faker.music.songName(),
                    time: "9:45",
                    unread: 5,
                    pinned: false,
                    about: this_user.about,
                }
            })
            state.direct_chat.conversations = list;
        },
        //Need to understand
        updateDirectConversation(state, action) {
            const user_id = window.localStorage.getItem("user_id");
            const this_conversation = action.payload.conversation;
            state.direct_chat.conversations = state.direct_chat.conversations.map((el) => {
                if (el.id !== this_conversation.id) {
                    return el;
                } else {
                    const user = this_conversation.participants?.find((el) => el.id.toString() !== user_id);
                    return {
                        id: this_conversation?.id,
                        user_id: user?.id,
                        name: `${user?.firstName} ${user?.lastName}`,
                        email: user?.email,
                        online: user?.status === "ONLINE",
                        img: user?.avatar,
                        msg: faker.music.songName(),
                        time: "9:45",
                        unread: 0,
                        pinned: false,
                    };
                }
            })
        },
        //Need to understand
        addDirectConversation(state, action) {
            const user_id = window.localStorage.getItem("user_id");
            const this_conversation = action.payload.conversation;
            const user = this_conversation.participants.find((el) => el.id.toString() !== user_id);

            state.direct_chat.conversations = state.direct_chat.conversations.filter(
                (el) => el?.id !== this_conversation.id);

            state.direct_chat.conversations.push({
                id: this_conversation?.id,
                user_id: user?.id,
                name: `${user?.firstName} ${user?.lastName}`,
                email: user?.email,
                online: user?.status === "ONLINE",
                img: user?.avatar,
                msg: faker.music.songName(),
                time: "9:45",
                unread: 0,
                pinned: false,
            })
        },
        setCurrentConversation(state, action) {
            const room_id = action.payload.room_id;
            const current_conversation = state.direct_chat.conversations.find((el) => el.id.toString() === room_id);
            state.direct_chat.current_conversation = current_conversation;
        },
        fetchDirectMessages(state, action) {
            const this_user_id = window.localStorage.getItem("user_id");
            const messages = action.payload.map((el) => {
                const lastMessage = el.messages && el.messages.length > 0 ? el.messages[el.messages.length - 1] : null;
                
                return {
                  id: el.id,
                  last_message: lastMessage ? lastMessage.text || lastMessage.mediaType : '', // Fallback to empty string if no message
                  last_message_time: lastMessage ? convertTimestamp(lastMessage.createdAt) : '', // Fallback to empty string if no message
                  messages: el.messages && el.messages.length > 0
                    ? el.messages.map((message) => ({
                        type: "msg",
                        subtype: message.type,
                        media: message.media,
                        mediaType: message.mediaType,
                        message: message.text,
                        incoming: message.to === this_user_id,
                        outgoing: message.from === this_user_id,
                        time: convertTimestamp(message.createdAt),
                      }))
                    : [], // Fallback to empty array if no messages
                };
              });

            state.direct_chat.messages = messages;
        },
        fetchCurrentMessages(state, action) {
            const this_user_id = window.localStorage.getItem("user_id");
            const messages = action.payload.messages;
            const formatted_messages = messages.map((el) => ({
                id: el.id,
                type: "msg",
                subtype: el.type,
                media: el.media,
                mediaType: el.mediaType,
                message: el.text,
                incoming: el.to === this_user_id,
                outgoing: el.from === this_user_id,
                time: convertTimestamp(el.createdAt),
            }));
            state.direct_chat.current_messages = formatted_messages;
        },
        addDirectMessage(state, action) {
            if (state.direct_chat.current_conversation.id === action.payload.message.id) {
                state.direct_chat.current_messages.push(action.payload.message);
            }
            state.direct_chat.messages = state.direct_chat.messages.map((el) => {
                if (el.id === action.payload.message.id) {
                    return {
                        ...el, 
                        messages: [...el.messages, action.payload.message],
                        last_message:action.payload.message.message ? action.payload.message.message : action.payload.message.mediaType,
                        last_message_time:action.payload.message.time,
                    }
                }
                return el;
            });
        },
        clearConversation() {
            return initialState;
        },
    }
});

export default slice.reducer;


export const FetchDirectConversations = () => {

    return async (dispatch, getState) => {
        dispatch(UpdateIsLoading({ isLoading: true, error: false }));

        await axios.get("/user/get-direct-conversations", {
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${getState().auth.token}`,
            }
        }).then((response) => {
            dispatch(slice.actions.fetchDirectConversations(response.data.data));
            dispatch(slice.actions.fetchDirectMessages(response.data.data));
            dispatch(UpdateIsLoading({ isLoading: false, error: false }));
        }).catch((error) => {
            console.log(error);
            dispatch(UpdateIsLoading({ isLoading: false, error: true }));
        })
    }
}

export const AddDirectConversation = ({ conversation }) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.addDirectConversation({ conversation }));
    }
};

export const UpdateDirectConversation = ({ conversation }) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.updateDirectConversation({ conversation }));
    }
};

export const SetCurrentConversation = (current_conversation) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.setCurrentConversation(current_conversation));
    };
};


export const FetchCurrentMessages = ({ messages }) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.fetchCurrentMessages({ messages }));
    }
}

export const AddDirectMessage = (message) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.addDirectMessage({ message }));
    }
};

export const AddIncomingMessage = (message) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.addIncomingMessage({ message }));
    }
};

export const ClearConversation = () => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.clearConversation());
    }
}